// src/pages/StoragePages.js
import { useState, useEffect, useCallback } from 'react';
import { storageAPI, destinationsAPI, settingsAPI, usersAPI, authAPI } from '../services/api';
import { Card, StatCard, Badge, Btn, DbIcon, Modal, Field, Toggle, toast } from '../components/UI';
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import { format } from 'date-fns';

function fmtBytes(b, short) {
  if (!b || b === 0) return '0 B';
  const u = ['B','KB','MB','GB','TB'];
  const i = Math.floor(Math.log(b) / Math.log(1024));
  const v = (b / Math.pow(1024, i)).toFixed(1);
  return short ? v + ' ' + u[i] : v + ' ' + u[i];
}

// ──────────────────────────────────────────────────────────────────────────────
// STORAGE ANALYTICS
// ──────────────────────────────────────────────────────────────────────────────
export function StoragePage() {
  const [data, setData]   = useState(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try { setData(await storageAPI.stats()); }
    catch (e) { toast(e.message, 'error'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  if (loading) return <PageShell title="Storage Analytics" sub="30-day overview"><div style={{ textAlign: 'center', padding: 60, color: '#6e7681' }}>Loading...</div></PageShell>;

  const totalBytes   = data?.byType?.reduce((a, r) => a + (r.total_bytes || 0), 0) || 0;
  const totalRuns    = data?.byType?.reduce((a, r) => a + (r.run_count || 0), 0) || 0;
  const totalSuccess = data?.byType?.reduce((a, r) => a + (r.success_count || 0), 0) || 0;
  const totalFailed  = data?.byType?.reduce((a, r) => a + (r.fail_count || 0), 0) || 0;
  const avgBytes     = totalRuns > 0 ? totalBytes / totalRuns : 0;
  const successRate  = totalRuns > 0 ? Math.round(totalSuccess / totalRuns * 100) : 100;

  const PIE_COLORS = { mysql: '#e36209', postgresql: '#7ca8f8', redis: '#f85149' };

  const trendData = (data?.trend || []).map(r => ({
    date: format(new Date(r.date), 'MMM d'),
    size: Math.round(r.total_bytes / 1024 / 1024),
    runs: r.run_count,
  }));

  const targetData = (data?.byTarget || []).map(r => ({
    name: r.name.length > 14 ? r.name.substring(0, 12) + '…' : r.name,
    size: Math.round((r.total_bytes || 0) / 1024 / 1024),
  }));

  return (
    <PageShell title="Storage Analytics" sub="30-day backup data overview across all targets">
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5,1fr)', gap: 12 }}>
        <StatCard label="Total Data (30D)"  value={fmtBytes(totalBytes)}     sub="all destinations"  accent="blue"   />
        <StatCard label="Total Runs (30D)"  value={totalRuns}                sub="across all targets" color="cyan"   accent="cyan"   />
        <StatCard label="Success Rate"      value={successRate + '%'}        sub="jobs completed OK"  color="green"  accent="green"  />
        <StatCard label="Failed Runs"       value={totalFailed}              sub="need investigation" color={totalFailed > 0 ? 'red' : 'white'} accent="red" />
        <StatCard label="Avg Backup Size"   value={fmtBytes(avgBytes)}       sub="per run average"   accent="purple" />
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1.5fr 1fr', gap: 16 }}>
        <Card title="Daily Backup Size — 14 Days" action={<span style={{ fontSize: 11, color: '#6e7681' }}>Successful runs only</span>}>
          <ResponsiveContainer width="100%" height={180}>
            <LineChart data={trendData} margin={{ left: -20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
              <XAxis dataKey="date" tick={{ fill: '#6e7681', fontSize: 9 }} tickLine={false} />
              <YAxis tick={{ fill: '#6e7681', fontSize: 9 }} tickLine={false} axisLine={false} unit=" MB" />
              <Tooltip contentStyle={{ background: '#1c2128', border: '1px solid #30363d', borderRadius: 6, fontSize: 11 }} />
              <Line type="monotone" dataKey="size" stroke="'#58a6ff'" strokeWidth={1.5} dot={{ fill: '#58a6ff', r: 3 }} name="Size MB" />
            </LineChart>
          </ResponsiveContainer>
        </Card>

        <Card title="Storage by DB Type">
          <ResponsiveContainer width="100%" height={180}>
            <PieChart>
              <Pie data={data?.byType || []} dataKey="total_bytes" nameKey="db_type" cx="40%" cy="50%" innerRadius={50} outerRadius={80}>
                {(data?.byType || []).map((e, i) => <Cell key={i} fill={PIE_COLORS[e.db_type] || '#58a6ff'} />)}
              </Pie>
              <Tooltip formatter={(v) => fmtBytes(v)} contentStyle={{ background: '#1c2128', border: '1px solid #30363d', borderRadius: 6, fontSize: 11 }} />
            </PieChart>
          </ResponsiveContainer>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginTop: 8 }}>
            {(data?.byType || []).map(r => (
              <div key={r.db_type} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12 }}>
                <span style={{ width: 10, height: 10, borderRadius: 2, background: PIE_COLORS[r.db_type], display: 'inline-block', flexShrink: 0 }} />
                <DbIcon type={r.db_type} size={18} />{r.db_type} — {fmtBytes(r.total_bytes)} · {r.run_count} runs
              </div>
            ))}
          </div>
        </Card>
      </div>

      <Card title="Per-Target Breakdown (30 Days)">
        <ResponsiveContainer width="100%" height={140}>
          <BarChart data={targetData} margin={{ left: -20 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
            <XAxis dataKey="name" tick={{ fill: '#6e7681', fontSize: 9 }} tickLine={false} />
            <YAxis tick={{ fill: '#6e7681', fontSize: 9 }} tickLine={false} axisLine={false} unit=" MB" />
            <Tooltip contentStyle={{ background: '#1c2128', border: '1px solid #30363d', borderRadius: 6, fontSize: 11 }} />
            <Bar dataKey="size" fill="'#e36209'" radius={[4,4,0,0]} name="Size MB" />
          </BarChart>
        </ResponsiveContainer>
        <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 16 }}>
          <thead><tr>{['Target','DB Type','Total Runs','Total Size','Last Run','Last Status'].map(h => (
            <th key={h} style={{ textAlign: 'left', fontSize: 10, fontWeight: 600, color: '#6e7681', letterSpacing: '.07em', textTransform: 'uppercase', padding: '6px 12px', borderBottom: '1px solid #30363d' }}>{h}</th>
          ))}</tr></thead>
          <tbody>
            {(data?.byTarget || []).map(r => (
              <tr key={r.name}
                onMouseEnter={e => e.currentTarget.style.background = '#1c2128'}
                onMouseLeave={e => e.currentTarget.style.background = ''}>
                <td style={{ padding: '8px 12px', borderBottom: '1px solid #30363d', fontSize: 12 }}><strong>{r.name}</strong></td>
                <td style={{ padding: '8px 12px', borderBottom: '1px solid #30363d' }}><Badge type={r.db_type} small>{r.db_type?.toUpperCase()}</Badge></td>
                <td style={{ padding: '8px 12px', borderBottom: '1px solid #30363d', fontSize: 12, color: '#8b949e' }}>{r.run_count || 0}</td>
                <td style={{ padding: '8px 12px', borderBottom: '1px solid #30363d', fontSize: 12, color: '#8b949e' }}>{fmtBytes(r.total_bytes)}</td>
                <td style={{ padding: '8px 12px', borderBottom: '1px solid #30363d', fontSize: 12, color: '#8b949e' }}>{r.last_run ? format(new Date(r.last_run), 'dd MMM, hh:mm a') : '—'}</td>
                <td style={{ padding: '8px 12px', borderBottom: '1px solid #30363d' }}>{r.last_status ? <Badge type={r.last_status}>{r.last_status.toUpperCase()}</Badge> : <span style={{ color: '#6e7681' }}>—</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>
    </PageShell>
  );
}

// ──────────────────────────────────────────────────────────────────────────────
// PRIMARY DC STORAGE (reads from /api/fs/primary-mount)
// ──────────────────────────────────────────────────────────────────────────────
export function PrimaryDCPage() {
  const [data,     setData]     = useState(null);
  const [loading,  setLoading]  = useState(true);
  const [expanded, setExpanded] = useState({});

  const load = useCallback(async () => {
    setLoading(true);
    try { setData(await storageAPI.primaryMount()); }
    catch(e) { toast(e.message, 'error'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const storage  = data?.storage || {};
  const pct      = parseInt(storage.usePercent) || 0;
  const barColor = pct >= 90 ? '#f85149' : pct >= 80 ? '#e3b341' : '#3fb950';

  // Flatten all files across all days for a directory, newest first
  function allFiles(folder) {
    return Object.entries(folder.days || {})
      .sort(([a],[b]) => b.localeCompare(a))   // newest date folder first
      .flatMap(([, files]) => files)
      .sort((a,b) => (b.mtime||0)-(a.mtime||0));
  }

  function fmtDate(dateKey) {
    try {
      const d = new Date(dateKey);
      return d.toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric' });
    } catch { return dateKey; }
  }

  return (
    <PageShell
      title={<><i className="ti ti-device-floppy" style={{marginRight:8,color:'#58a6ff'}}/> Primary DC Storage</>}
      sub={<>NFS: <span style={{color:'#39d0d8',fontFamily:'monospace'}}>{process.env.REACT_APP_PRIMARY_HOST||'10.180.0.90'}:/home</span> → <span style={{color:'#3fb950',fontFamily:'monospace'}}>/primary-db-backup</span></>}
      action={<button onClick={load} style={{display:'flex',alignItems:'center',gap:5,padding:'6px 13px',borderRadius:8,border:'1px solid #444c56',background:'#21262d',color:'#e6edf3',fontSize:12,cursor:'pointer'}}><i className="ti ti-refresh"/> Refresh</button>}
    >
      {/* Disk stats */}
      <div style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:12}}>
        {[
          {icon:'device-floppy', label:'Total Disk Pool',         value:storage.size||'—',  color:'#58a6ff', bg:'#1c2a3a'},
          {icon:'chart-bar',     label:`Used (${storage.usePercent||'—'})`, value:storage.used||'—', color:barColor, bg:'#1c2128', bar:true},
          {icon:'check',         label:'Available Free Space',    value:storage.avail||'—', color:'#3fb950', bg:'#122a1e'},
        ].map(({icon,label,value,color,bg,bar})=>(
          <div key={label} style={{background:'#161b22',border:'1px solid #30363d',borderRadius:12,padding:'14px 16px',display:'flex',alignItems:'center',gap:14}}>
            <div style={{width:42,height:42,borderRadius:10,background:bg,display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}>
              <i className={`ti ti-${icon}`} style={{fontSize:20,color}}/>
            </div>
            <div style={{flex:1}}>
              <div style={{fontSize:10,color:'#6e7681',letterSpacing:'.07em',textTransform:'uppercase',fontWeight:600,marginBottom:4}}>{label}</div>
              <div style={{fontSize:22,fontWeight:500,color}}>{value}</div>
              {bar && <div style={{width:'100%',height:6,background:'#21262d',borderRadius:3,overflow:'hidden',marginTop:5}}>
                <div style={{height:'100%',width:`${pct}%`,background:barColor,borderRadius:3}}/>
              </div>}
            </div>
          </div>
        ))}
      </div>

      {/* Repository tree */}
      <div style={{background:'#161b22',border:'1px solid #30363d',borderRadius:12,overflow:'hidden'}}>
        <div style={{padding:'12px 16px',borderBottom:'1px solid #30363d',display:'flex',alignItems:'center',justifyContent:'space-between'}}>
          <span style={{fontSize:11,fontWeight:600,color:'#8b949e',letterSpacing:'.06em',textTransform:'uppercase'}}>
            Repository hierarchy — {(data?.tree||[]).length} databases · sorted by recent activity
          </span>
          <span style={{fontSize:11,color:'#6e7681'}}>{(data?.tree||[]).reduce((s,f)=>s+f.totalFiles,0)} total files</span>
        </div>

        {loading ? (
          <div style={{textAlign:'center',padding:40,color:'#6e7681'}}>Loading...</div>
        ) : (data?.tree||[]).length === 0 ? (
          <div style={{textAlign:'center',padding:48,color:'#6e7681'}}>
            <i className="ti ti-folder-off" style={{fontSize:40,display:'block',marginBottom:12,color:'#444c56'}}/>
            No backup files found in /primary-db-backup
          </div>
        ) : (
          <div>
            {(data?.tree||[]).map(folder => {
              const isOpen   = expanded[folder.id];
              const recent   = folder.recentFile;
              const dayKeys  = Object.keys(folder.days||{}).sort((a,b)=>b.localeCompare(a));

              return (
                <div key={folder.id} style={{borderBottom:'1px solid #21262d'}}>
                  {/* DB folder row */}
                  <div onClick={()=>setExpanded(p=>({...p,[folder.id]:!p[folder.id]}))}
                    style={{display:'flex',alignItems:'center',gap:10,padding:'10px 16px',
                      cursor:'pointer',background:isOpen?'#1c2128':'transparent'}}
                    onMouseEnter={e=>{if(!isOpen)e.currentTarget.style.background='#1c2128'}}
                    onMouseLeave={e=>{if(!isOpen)e.currentTarget.style.background=''}}>
                    <i className={`ti ti-caret-${isOpen?'down':'right'}`} style={{fontSize:13,color:'#6e7681',flexShrink:0}}/>
                    <i className="ti ti-folder-filled" style={{fontSize:16,color:'#e3b341',flexShrink:0}}/>
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontSize:13,fontWeight:500,color:'#e6edf3'}}>{folder.folderName}</div>
                      {recent && (
                        <div style={{fontSize:10,color:'#6e7681',marginTop:1}}>
                          Latest: <span style={{color:'#39d0d8',fontFamily:'monospace'}}>{recent.filename}</span>
                          {' '}· {recent.size} · {recent.time}
                        </div>
                      )}
                    </div>
                    <div style={{textAlign:'right',flexShrink:0}}>
                      <div style={{fontSize:12,color:'#8b949e',fontWeight:500}}>{folder.totalFiles} files</div>
                      {dayKeys.length > 0 && <div style={{fontSize:10,color:'#6e7681'}}>{dayKeys.length} days</div>}
                    </div>
                  </div>

                  {/* Expanded: date folders with files */}
                  {isOpen && (
                    <div style={{borderTop:'1px solid #21262d',background:'#0d1117'}}>
                      {dayKeys.length === 0 ? (
                        <div style={{padding:'10px 32px',color:'#6e7681',fontSize:12}}>No backup files found</div>
                      ) : dayKeys.map(dateKey => (
                        <div key={dateKey}>
                          {/* Date header */}
                          <div style={{padding:'6px 32px 4px',background:'#161b22',borderBottom:'1px solid #21262d',
                            display:'flex',alignItems:'center',gap:8}}>
                            <i className="ti ti-calendar" style={{fontSize:12,color:'#58a6ff'}}/>
                            <span style={{fontSize:11,fontWeight:600,color:'#58a6ff'}}>{fmtDate(dateKey)}</span>
                            <span style={{fontSize:10,color:'#6e7681'}}>({(folder.days[dateKey]||[]).length} files)</span>
                          </div>
                          {/* Files — newest first */}
                          {(folder.days[dateKey]||[]).map((file,i) => (
                            <div key={file.filename} style={{
                              display:'flex',alignItems:'center',gap:10,
                              padding:'7px 32px 7px 48px',
                              borderBottom:'1px solid #1c2128',
                              background: i===0?'rgba(88,166,255,0.04)':'transparent',
                            }}>
                              <i className="ti ti-file-zip" style={{fontSize:13,color: file.status==='Verified'?'#39d0d8':'#f85149',flexShrink:0}}/>
                              <span style={{flex:1,fontSize:11,fontFamily:'monospace',color:'#e6edf3',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}
                                title={file.filename}>
                                {i===0 && <span style={{fontSize:9,background:'#1c2a3a',color:'#58a6ff',padding:'1px 5px',borderRadius:3,marginRight:6,fontFamily:'inherit'}}>LATEST</span>}
                                {file.filename}
                              </span>
                              <span style={{fontSize:11,color:'#8b949e',whiteSpace:'nowrap',flexShrink:0}}>{file.size}</span>
                              <span style={{fontSize:10,color:'#6e7681',whiteSpace:'nowrap',flexShrink:0}}>{file.time}</span>
                              <span style={{fontSize:10,padding:'1px 6px',borderRadius:10,flexShrink:0,
                                background: file.status==='Verified'?'#1a3428':'#3d1a18',
                                color: file.status==='Verified'?'#3fb950':'#f85149'}}>
                                {file.status}
                              </span>
                            </div>
                          ))}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </PageShell>
  );
}


export function RemotePage() {
  return (
    <PageShell title="OnSite Remote Backup" sub={<>Remote SFTP: <span style={{ color: '#39d0d8', fontFamily: 'monospace' }}>192.168.2.10</span> → <span style={{ color: '#3fb950', fontFamily: 'monospace' }}>/backups/remote</span></>}>
      <Card>
        <div style={{ textAlign: 'center', padding: 40, color: '#6e7681' }}>
          <i className="ti ti-building" style={{ fontSize: 40, display: 'block', marginBottom: 12 }} />
          Remote site volume tree loads via direct SFTP connection.<br />Implement <code style={{ fontFamily: 'monospace', color: '#39d0d8' }}>/api/fs/remote-mount</code> in <code style={{ fontFamily: 'monospace' }}>routes/fs.js</code> to enable.
        </div>
      </Card>
    </PageShell>
  );
}

