export function SettingsPage() {
  const [info, setInfo] = useState(null);

  useEffect(() => {
    settingsAPI.get().then(setInfo).catch(() => {});
  }, []);

  const row = (label, value, hint) => (
    <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', padding: '10px 0', borderBottom: '1px solid #30363d' }}>
      <div>
        <div style={{ fontSize: 13, color: '#e6edf3' }}>{label}</div>
        {hint && <div style={{ fontSize: 11, color: '#6e7681', marginTop: 2 }}>{hint}</div>}
      </div>
      <div style={{ fontSize: 12, fontFamily: 'monospace', color: '#39d0d8', textAlign: 'right', maxWidth: 260, wordBreak: 'break-all' }}>{value}</div>
    </div>
  );

  return (
    <PageShell title="Settings" sub="System-wide configuration for BackupVault">
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
        <Card title="System Information">
          {info ? <>
            {row('Backup Directory', info.backup_dir)}
            {row('Timezone', info.timezone)}
            {row('Node.js Version', info.node_version)}
            {row('Server Uptime', Math.floor(info.uptime_seconds / 60) + ' minutes')}
            {row('Application Version', info.version)}
          </> : <div style={{ color: '#6e7681' }}>Loading...</div>}
        </Card>

        <Card title="Default Job Settings">
          {row('Default Retention', info?.retention_default + ' days', 'Applied to new jobs unless overridden')}
          {row('Max Concurrent Jobs', info?.max_concurrent_jobs, 'Parallel backup workers')}
          {row('Notification Email', info?.notification_email || '(not set)')}
          {row('Slack Webhook', info?.slack_webhook ? '✓ Configured' : '(not set)')}
        </Card>

        <Card title="Nginx Config" style={{ gridColumn: 'span 2' }}>
          <pre style={{ fontFamily: 'monospace', fontSize: 11, color: '#8b949e', background: '#1c2128', border: '1px solid #30363d', borderRadius: 8, padding: 14, overflowX: 'auto', lineHeight: 1.7 }}>
{`server {
    listen 443 ssl http2;
    server_name backupvault.worktual.tech;
    root /var/www/backupvault/frontend/build;

    ssl_certificate /etc/ssl/worktual.tech/STAR.worktual.tech.fullchain.pem;
    ssl_certificate_key /etc/ssl/worktual.tech/STAR.worktual.tech_key.txt;

    location / { try_files $uri $uri/ /index.html; }

    location /api/ { proxy_pass http://127.0.0.1:4100; }

    location /ws {
        proxy_pass http://127.0.0.1:4100/ws;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "Upgrade";
    }
}`}
          </pre>
          <div style={{ marginTop: 10, fontSize: 12, color: '#8b949e' }}>
            Build: <code style={{ fontFamily: 'monospace', color: '#39d0d8' }}>npm run build</code> → copy <code style={{ fontFamily: 'monospace', color: '#39d0d8' }}>build/</code> to <code style={{ fontFamily: 'monospace', color: '#39d0d8' }}>/var/www/backupvault/frontend/build</code>
          </div>
        </Card>
      </div>
    </PageShell>
  );
}

// ──────────────────────────────────────────────────────────────────────────────
// USER MANAGEMENT (admin portal — creates users via /auth/register)
// ──────────────────────────────────────────────────────────────────────────────
export function UsersPage() {
  const [users, setUsers]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal]   = useState(false);
  const [form, setForm]     = useState({ name: '', email: '', password: '', confirm: '' });
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  const load = useCallback(async () => {
    try { setUsers(await usersAPI.list()); }
    catch (e) {
      // /api/users not yet in backend — show empty gracefully
      setUsers([]);
    }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  async function handleCreate(e) {
    e.preventDefault();
    if (form.password !== form.confirm) return setError('Passwords do not match');
    setSaving(true); setError('');
    try {
      await authAPI.register(form.name, form.email, form.password);
      toast('User created successfully');
      setModal(false);
      setForm({ name: '', email: '', password: '', confirm: '' });
      load();
    } catch (err) { setError(err.message); }
    finally { setSaving(false); }
  }

  async function handleRemove(id, name) {
    if (!window.confirm(`Remove user "${name}"? This cannot be undone.`)) return;
    try { await usersAPI.remove(id); toast('User removed'); load(); }
    catch (e) { toast('Failed: ' + e.message, 'error'); }
  }

  return (
    <PageShell title="User Management" sub="Manage administrator access to BackupVault" action={<Btn variant="primary" icon="user-plus" onClick={() => { setForm({ name: '', email: '', password: '', confirm: '' }); setError(''); setModal(true); }}>+ Add User</Btn>}>
      <Card>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr>{['#','Name','Email','Created At','Actions'].map(h => (
              <th key={h} style={{ textAlign: 'left', fontSize: 10, fontWeight: 600, color: '#6e7681', letterSpacing: '.07em', textTransform: 'uppercase', padding: '8px 14px', borderBottom: '1px solid #30363d' }}>{h}</th>
            ))}</tr>
          </thead>
          <tbody>
            {loading ? <tr><td colSpan={5} style={{ textAlign: 'center', padding: 40, color: '#6e7681' }}>Loading...</td></tr>
            : users.length === 0 ? (
              <tr><td colSpan={5} style={{ textAlign: 'center', padding: 40, color: '#6e7681' }}>
                <i className="ti ti-user-off" style={{ fontSize: 36, display: 'block', marginBottom: 10 }} />
                No users found. Add <code style={{ fontFamily: 'monospace', color: '#39d0d8' }}>GET /api/users</code> to your backend to list users,<br />or create the first admin account below.
              </td></tr>
            ) : users.map((u, i) => (
              <tr key={u.id}
                onMouseEnter={e => e.currentTarget.style.background = '#1c2128'}
                onMouseLeave={e => e.currentTarget.style.background = ''}>
                <td style={{ padding: '10px 14px', borderBottom: '1px solid #30363d', color: '#6e7681', fontFamily: 'monospace', fontSize: 12 }}>{i + 1}</td>
                <td style={{ padding: '10px 14px', borderBottom: '1px solid #30363d' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <div style={{ width: 32, height: 32, borderRadius: '50%', background: '#1c2a3a', color: '#58a6ff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, fontWeight: 700 }}>
                      {u.name?.charAt(0)?.toUpperCase()}
                    </div>
                    <strong style={{ fontSize: 13 }}>{u.name}</strong>
                  </div>
                </td>
                <td style={{ padding: '10px 14px', borderBottom: '1px solid #30363d', fontSize: 12, color: '#39d0d8', fontFamily: 'monospace' }}>{u.email}</td>
                <td style={{ padding: '10px 14px', borderBottom: '1px solid #30363d', fontSize: 12, color: '#8b949e' }}>{u.created_at ? format(new Date(u.created_at), 'dd MMM yyyy, hh:mm a') : '—'}</td>
                <td style={{ padding: '10px 14px', borderBottom: '1px solid #30363d' }}>
                  <Btn variant="danger" size="sm" icon="trash" onClick={() => handleRemove(u.id, u.name)}>Remove</Btn>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>

      <Modal open={modal} onClose={() => setModal(false)} title="Create Admin User">
        <form onSubmit={handleCreate}>
          <Field label="Full Name" required>
            <input value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} placeholder="Admin Name" style={{ width: '100%' }} required />
          </Field>
          <Field label="Email Address" required>
            <input type="email" value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))} placeholder="admin@worktual.tech" style={{ width: '100%' }} required />
          </Field>
          <Field label="Password" required hint="Minimum 8 characters">
            <input type="password" value={form.password} onChange={e => setForm(p => ({ ...p, password: e.target.value }))} style={{ width: '100%' }} required minLength={8} />
          </Field>
          <Field label="Confirm Password" required>
            <input type="password" value={form.confirm} onChange={e => setForm(p => ({ ...p, confirm: e.target.value }))} style={{ width: '100%' }} required />
          </Field>
          {error && <div style={{ color: '#f85149', fontSize: 12, marginBottom: 12 }}>{error}</div>}
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 4 }}>
            <Btn variant="ghost" type="button" onClick={() => setModal(false)}>Cancel</Btn>
            <Btn variant="primary" loading={saving}>Create User</Btn>
          </div>
        </form>
      </Modal>
    </PageShell>
  );
}

